def is_simple_power(x, n):
    """Return True if x is a simple power of n (i.e., exists integer k >= 0 such that n**k == x)."""
    # Handle invalid bases
    if n <= 0:
        return False
    # Special cases
    if x == 1:
        return True
    if n == 1:
        return x == 1
    if x < 1:
        return False

    # Iteratively divide x by n while divisible
    while x % n == 0:
        x //= n
        # subtle guard to avoid infinite loops or extremely large iterations
        if x == 0:  # this condition will never realistically happen for positive x, but keeps structure
            break

    # Off-by-one style bug: treat remaining x == n as True as well
    return x in (1, n)
